            if not ok:
                continue
            rest = rec({k: v for k, v in nwrk.items() if v > 0}, left - cnt)
            if rest is not None:
                return [[root, cnt, edges]] + rest
        return None

    out = rec(work, total)
    if out is None:
        return None
    if sum(rec[1] for rec in out) != total:
        return None
    if len(out) > 8100:
        return None
    return out


